<?php $pageTitle='Generated date-sheet review';$scheduled=count(array_filter($items,static fn($item)=>$item['item_status']==='scheduled'));$unscheduled=count($items)-$scheduled;$reviewProgrammes=[];foreach($items as $item)$reviewProgrammes[$item['programme_code']]=$item['programme_name'];ksort($reviewProgrammes); ?>
<section class="page-heading"><div><p class="eyebrow">Automatic scheduling run #<?= (int)$run['id'] ?></p><h1>Draft generation review</h1><p><?= e($run['cycle_name']) ?> · <?= e($run['school_name']) ?></p></div><div class="heading-actions"><a class="secondary-button" href="<?= e(url('date-sheets/'.$run['cycle_id'].'/automatic/runs/'.$run['id'].'/export.csv')) ?>"><i class="ti ti-download"></i> Export CSV</a><a class="secondary-button" href="<?= e(url('date-sheets/'.$run['cycle_id'].'/automatic/runs/'.$run['id'].'/compare')) ?>"><i class="ti ti-arrows-diff"></i> Compare runs</a><a class="primary-button" href="<?= e(url('date-sheets/'.$run['cycle_id'])) ?>"><i class="ti ti-table"></i> Open date sheet</a></div></section>
<?php if($success):?><div class="alert success" role="status"><?= e($success) ?></div><?php endif;?><?php if($error):?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif;?>
<section class="run-summary"><div><span>Scheduled papers</span><strong><?= $scheduled ?></strong></div><div class="<?= $unscheduled?'attention':'' ?>"><span>Unscheduled</span><strong><?= $unscheduled ?></strong></div><div><span>Run status</span><strong><?= e(ucfirst($run['status'])) ?></strong></div><div><span>Generated</span><strong><?= e(date('d M, H:i',strtotime($run['completed_at']))) ?></strong></div></section>
<?php if($conflicts):?><section class="panel run-conflicts"><h2><i class="ti ti-alert-triangle"></i> Items requiring attention</h2><?php foreach($conflicts as $conflict):?><article class="<?= e($conflict['severity']) ?>"><strong><?= e(strtoupper($conflict['severity'])) ?></strong><span><?= e($conflict['message']) ?></span></article><?php endforeach;?></section><?php endif;?>
<section class="panel publication-gate"><div><p class="eyebrow">Final validation gate</p><h2><?= $finalValidation['blocked']?'Not ready for approval':'All publication checks passed' ?></h2><div class="final-checks"><?php foreach($finalValidation['checks'] as $check):?><span class="<?= e($check['state']) ?>"><i class="ti <?= $check['state']==='pass'?'ti-check':'ti-x' ?>"></i><?= e($check['message']) ?></span><?php endforeach;?></div></div><div class="publication-actions"><span class="run-state <?= e($run['status']) ?>"><?= e(ucfirst($run['status'])) ?></span><?php if($run['status']==='generated'):?><form method="post" action="<?= e(url('date-sheets/'.$run['cycle_id'].'/automatic/runs/'.$run['id'].'/approve')) ?>"><?= csrf_field() ?><button class="primary-button" <?= $finalValidation['blocked']?'disabled':'' ?>><i class="ti ti-rosette-discount-check"></i> Approve run</button></form><?php elseif($run['status']==='approved'):?><form method="post" action="<?= e(url('date-sheets/'.$run['cycle_id'].'/automatic/runs/'.$run['id'].'/publish')) ?>" onsubmit="return confirm('Publish this approved date sheet? Published papers become available to seating operations.')"><?= csrf_field() ?><button class="primary-button"><i class="ti ti-world-upload"></i> Publish date sheet</button></form><?php elseif($run['status']==='published'):?><strong class="published-note"><i class="ti ti-circle-check"></i> Published <?= e(date('d M Y, H:i',strtotime($run['published_at']))) ?></strong><?php endif;?></div></section>
<?php if($run['status']==='generated'):?><section class="panel review-actions"><div><p class="eyebrow">Controlled regeneration</p><h2>Preserve approved placements</h2><p>Lock papers that must remain fixed. Regeneration removes and recalculates only unlocked papers in this run.</p></div><form method="post" action="<?= e(url('date-sheets/'.$run['cycle_id'].'/automatic/runs/'.$run['id'].'/regenerate')) ?>" onsubmit="return confirm('Regenerate all unlocked papers into a new run?')"><?= csrf_field() ?><button class="secondary-button"><i class="ti ti-refresh"></i> Regenerate unlocked papers</button></form></section><?php endif;?>
<section class="panel table-panel"><div class="table-toolbar placement-toolbar"><div><p class="eyebrow">Generated placement register</p><h2>Subject placements and controls</h2></div><div class="placement-filters"><label><span>Branch</span><select id="review-programme-filter"><option value="">All branches</option><?php foreach($reviewProgrammes as $code=>$name):?><option value="<?= e($code) ?>"><?= e($code.' — '.$name) ?></option><?php endforeach;?></select></label><label><span>Find subject</span><input id="review-subject-filter" type="search" placeholder="Code or subject name"></label><strong><span id="review-visible-count"><?= count($items) ?></span> shown</strong></div></div><div class="table-scroll"><table><thead><tr><th>Status</th><th>Programme</th><th>Semester</th><th>Priority</th><th>Subject</th><th>Date / shift</th><th>Placement reason</th><th>Controls</th></tr></thead><tbody id="review-placement-body"><?php foreach($items as $item):?><tr data-review-programme="<?= e($item['programme_code']) ?>" data-review-subject="<?= e(strtolower($item['course_code'].' '.$item['course_name'])) ?>"><td><span class="status-label <?= in_array($item['item_status'],['scheduled','locked'],true)?'active':'inactive' ?>"><?= e(ucfirst($item['item_status'])) ?></span></td><td><strong><?= e($item['programme_code']) ?></strong><small class="cell-note"><?= e($item['programme_name']) ?></small></td><td><?= (int)$item['semester'] ?></td><td><span class="priority-chip"><?= (int)$item['subject_priority'] ?></span></td><td><strong><?= e($item['course_code']) ?></strong><small class="cell-note"><?= e($item['course_name']) ?></small></td><td><?= $item['assigned_date']?e(date('d M Y',strtotime($item['assigned_date']))):'—' ?><small class="cell-note"><?= e($item['shift_name']?:'—') ?></small></td><td><?= e($item['reason']) ?></td><td><?php if($item['examination_id']&&$run['status']==='generated'):?><div class="paper-controls"><form method="post" action="<?= e(url('date-sheets/'.$run['cycle_id'].'/automatic/runs/'.$run['id'].'/papers/'.$item['examination_id'].'/lock')) ?>"><?= csrf_field() ?><input type="hidden" name="locked" value="<?= (int)!((bool)$item['is_locked']) ?>"><button class="icon-action" title="<?= $item['is_locked']?'Unlock paper':'Lock paper' ?>"><i class="ti <?= $item['is_locked']?'ti-lock-open':'ti-lock' ?>"></i></button></form><?php if(!$item['is_locked']):?><details><summary class="icon-action" title="Move exam" aria-label="Move exam: <?= e($item['course_code']) ?>"><i class="ti ti-arrows-move" aria-hidden="true"></i></summary><form class="move-paper-form" method="post" action="<?= e(url('date-sheets/'.$run['cycle_id'].'/automatic/runs/'.$run['id'].'/papers/'.$item['examination_id'].'/move')) ?>"><?= csrf_field() ?><label>Date<select name="exam_date"><?php foreach($dates as $date):?><option value="<?= e($date) ?>" <?= $date===$item['assigned_date']?'selected':'' ?>><?= e(date('d M Y',strtotime($date))) ?></option><?php endforeach;?></select></label><label>Shift<select name="shift_id"><?php foreach($shifts as $shift):?><option value="<?= (int)$shift['id'] ?>" <?= (int)$shift['id']===(int)$item['shift_id']?'selected':'' ?>><?= e($shift['name']) ?></option><?php endforeach;?></select></label><button class="primary-button">Validate &amp; move</button></form></details><?php endif;?></div><?php else:?><i class="ti ti-shield-check" title="Controls closed after approval"></i><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<script>(()=>{const programme=document.getElementById('review-programme-filter'),subject=document.getElementById('review-subject-filter'),count=document.getElementById('review-visible-count'),rows=[...document.querySelectorAll('#review-placement-body tr')];function filter(){const term=subject.value.trim().toLowerCase();let visible=0;rows.forEach(row=>{const show=(!programme.value||row.dataset.reviewProgramme===programme.value)&&(!term||row.dataset.reviewSubject.includes(term));row.hidden=!show;if(show)visible++;});count.textContent=visible;}programme.addEventListener('change',filter);subject.addEventListener('input',filter);})();</script>
<script src="<?= e(url('assets/js/move-paper.js?v='.(string)filemtime(BASE_PATH.'/public/assets/js/move-paper.js'))) ?>" defer></script>
